-- Public-assistant knowledge store. Review/apply only to the isolated CMS project.
-- It never reads portal, application, student or uploaded private-document tables.
begin;
create extension if not exists vector with schema extensions;
create table public.public_assistant_sources (id uuid primary key default gen_random_uuid(), source_type text not null check (source_type in ('course','page','document','faq')), source_key text not null, canonical_url text not null check (canonical_url like '/%' or canonical_url like 'https://%'), title text not null, publication_status text not null default 'staged' check (publication_status in ('staged','published','unpublished','archived')), source_version text not null, content_hash text not null, effective_at timestamptz, indexed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (source_type, source_key, source_version));
create table public.public_assistant_chunks (id uuid primary key default gen_random_uuid(), source_id uuid not null references public.public_assistant_sources(id) on delete cascade, ordinal integer not null check (ordinal >= 0), heading text, content text not null, content_tsv tsvector generated always as (to_tsvector('english', coalesce(heading, '') || ' ' || content)) stored, content_hash text not null, page_reference text, course_code text, embedding extensions.vector(1536), embedding_model text, embedding_dimensions integer, created_at timestamptz not null default now(), unique (source_id, ordinal, content_hash));
create index public_assistant_chunks_tsv_idx on public.public_assistant_chunks using gin (content_tsv); create index public_assistant_chunks_embedding_idx on public.public_assistant_chunks using hnsw (embedding extensions.vector_cosine_ops) where embedding is not null; create index public_assistant_sources_public_idx on public.public_assistant_sources (publication_status, source_type, source_key);
create table public.public_assistant_faqs (id uuid primary key default gen_random_uuid(), question text not null, normalized_question text not null unique, answer text not null, source_url text not null check (source_url like '/%' or source_url like 'https://%'), status text not null default 'draft' check (status in ('draft','published','archived')), aliases text[] not null default '{}', source_version text not null default '1', updated_at timestamptz not null default now());
create table public.public_assistant_index_jobs (id uuid primary key default gen_random_uuid(), source_type text not null, source_key text not null, source_version text not null, state text not null default 'queued' check (state in ('queued','processing','succeeded','failed','cancelled')), attempt_count integer not null default 0, next_attempt_at timestamptz not null default now(), lease_token uuid, lease_expires_at timestamptz, error_code text, error text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(source_type,source_key,source_version)); create index public_assistant_index_jobs_ready_idx on public.public_assistant_index_jobs (state, next_attempt_at);
create table public.public_assistant_usage_events (id bigint generated always as identity primary key, kind text not null check(kind in ('embedding','generation','retrieval','rate_limited','index_failure')), request_key text, input_tokens integer not null default 0, output_tokens integer not null default 0, latency_ms integer, model text, created_at timestamptz not null default now());
create table public.public_assistant_answer_cache (cache_key text primary key, source_version text not null, answer jsonb not null, expires_at timestamptz not null, created_at timestamptz not null default now()); create table public.public_assistant_rate_limits (bucket text primary key, window_started_at timestamptz not null, request_count integer not null default 0, updated_at timestamptz not null default now());
create table public.public_assistant_generation_slots (slot text primary key, lease_token uuid, lease_expires_at timestamptz, updated_at timestamptz not null default now()); insert into public.public_assistant_generation_slots(slot) values ('generation-1'),('generation-2'); create table public.public_assistant_generation_budgets (period_start date primary key, requests integer not null default 0, input_tokens integer not null default 0, output_tokens integer not null default 0, updated_at timestamptz not null default now());
alter table public.public_assistant_sources enable row level security; alter table public.public_assistant_chunks enable row level security; alter table public.public_assistant_faqs enable row level security; alter table public.public_assistant_index_jobs enable row level security; alter table public.public_assistant_usage_events enable row level security; alter table public.public_assistant_answer_cache enable row level security; alter table public.public_assistant_rate_limits enable row level security; alter table public.public_assistant_generation_slots enable row level security; alter table public.public_assistant_generation_budgets enable row level security;
revoke all on public.public_assistant_sources, public.public_assistant_chunks, public.public_assistant_faqs, public.public_assistant_index_jobs, public.public_assistant_usage_events, public.public_assistant_answer_cache, public.public_assistant_rate_limits, public.public_assistant_generation_slots, public.public_assistant_generation_budgets from anon, authenticated;
create policy public_assistant_faq_staff_read on public.public_assistant_faqs for select to authenticated using (public.cms_is_staff()); create policy public_assistant_faq_admin_write on public.public_assistant_faqs for all to authenticated using (public.cms_is_admin()) with check (public.cms_is_admin());
create or replace function public.public_assistant_content_version() returns text language sql stable security definer set search_path=public as $$ select md5(coalesce((select string_agg(source_type||':'||source_key||':'||source_version,',' order by source_type,source_key) from public.public_assistant_sources where publication_status='published'),'')||'|'||coalesce((select string_agg(normalized_question||':'||source_version,',' order by normalized_question) from public.public_assistant_faqs where status='published'),'')); $$;
create or replace function public.public_assistant_search_chunks(p_query extensions.vector(1536),p_query_text text,p_course_code text default null,p_limit integer default 6) returns table(chunk_id uuid,title text,heading text,content text,canonical_url text,page_reference text,course_code text,lexical_rank real,semantic_distance real) language sql stable security invoker set search_path=public,extensions as $$ select c.id,s.title,c.heading,c.content,s.canonical_url,c.page_reference,c.course_code,ts_rank_cd(c.content_tsv,websearch_to_tsquery('english',p_query_text)),c.embedding <=> p_query from public.public_assistant_chunks c join public.public_assistant_sources s on s.id=c.source_id where s.publication_status='published' and c.embedding is not null and (p_course_code is null or c.course_code=p_course_code) order by (0.45*ts_rank_cd(c.content_tsv,websearch_to_tsquery('english',p_query_text)))+(0.55*(1-(c.embedding <=> p_query))) desc limit greatest(1,least(p_limit,8)); $$;
create or replace function public.public_assistant_claim_index_job() returns setof public.public_assistant_index_jobs language plpgsql security definer set search_path=public as $$ begin return query with candidate as (select id from public.public_assistant_index_jobs where (state='queued' and next_attempt_at<=now()) or (state='processing' and lease_expires_at<now()) order by next_attempt_at,created_at for update skip locked limit 1) update public.public_assistant_index_jobs j set state='processing',attempt_count=j.attempt_count+1,lease_token=gen_random_uuid(),lease_expires_at=now()+interval '3 minutes',updated_at=now() from candidate where j.id=candidate.id returning j.*; end; $$;
create or replace function public.public_assistant_finish_index_job(p_job uuid,p_lease uuid,p_source uuid) returns boolean language plpgsql security definer set search_path=public as $$ declare j public.public_assistant_index_jobs; begin select * into j from public.public_assistant_index_jobs where id=p_job and state='processing' and lease_token=p_lease and lease_expires_at>now() for update; if not found then return false; end if; if not exists(select 1 from public.public_assistant_sources where id=p_source and source_type=j.source_type and source_key=j.source_key and source_version=j.source_version and publication_status='staged') then return false; end if; update public.public_assistant_sources set publication_status='unpublished',updated_at=now() where source_type=j.source_type and source_key=j.source_key and publication_status='published'; update public.public_assistant_sources set publication_status='published',effective_at=now(),indexed_at=now(),updated_at=now() where id=p_source; update public.public_assistant_index_jobs set state='succeeded',lease_token=null,lease_expires_at=null,updated_at=now() where id=p_job; delete from public.public_assistant_answer_cache; return true; end; $$;
create or replace function public.public_assistant_fail_index_job(p_job uuid,p_lease uuid,p_error text) returns boolean language plpgsql security definer set search_path=public as $$ begin update public.public_assistant_index_jobs set state=case when attempt_count<3 then 'queued' else 'failed' end,next_attempt_at=now()+interval '30 seconds'*attempt_count,lease_token=null,lease_expires_at=null,error_code='index',error=left(p_error,500),updated_at=now() where id=p_job and state='processing' and lease_token=p_lease and lease_expires_at>now(); return found; end; $$;
create or replace function public.public_assistant_cancel_index_job(p_job uuid,p_lease uuid) returns boolean language sql security definer set search_path=public as $$ update public.public_assistant_index_jobs set state='cancelled',lease_token=null,lease_expires_at=null,updated_at=now() where id=p_job and state='processing' and lease_token=p_lease and lease_expires_at>now() returning true; $$;
create or replace function public.public_assistant_take_rate_limit(p_bucket text,p_limit integer,p_window_seconds integer) returns boolean language plpgsql security definer set search_path=public as $$ declare c integer; begin insert into public.public_assistant_rate_limits(bucket,window_started_at,request_count) values(p_bucket,now(),1) on conflict(bucket) do update set window_started_at=case when public_assistant_rate_limits.window_started_at+make_interval(secs=>p_window_seconds)<=now() then now() else public_assistant_rate_limits.window_started_at end,request_count=case when public_assistant_rate_limits.window_started_at+make_interval(secs=>p_window_seconds)<=now() then 1 else public_assistant_rate_limits.request_count+1 end,updated_at=now() returning request_count into c; return c<=p_limit; end; $$;
create or replace function public.public_assistant_take_generation_slot(p_daily_limit integer) returns uuid language plpgsql security definer set search_path=public as $$ declare t uuid:=gen_random_uuid(); s text; b integer; begin insert into public.public_assistant_generation_budgets(period_start,requests) values(current_date,1) on conflict(period_start) do update set requests=public_assistant_generation_budgets.requests+1,updated_at=now() returning requests into b; if b>p_daily_limit then return null; end if; select slot into s from public.public_assistant_generation_slots where lease_expires_at is null or lease_expires_at<now() order by slot for update skip locked limit 1; if s is null then return null; end if; update public.public_assistant_generation_slots set lease_token=t,lease_expires_at=now()+interval '45 seconds',updated_at=now() where slot=s; return t; end; $$;
create or replace function public.public_assistant_release_generation_slot(p_lease uuid,p_input_tokens integer default 0,p_output_tokens integer default 0) returns boolean language plpgsql security definer set search_path=public as $$ begin update public.public_assistant_generation_slots set lease_token=null,lease_expires_at=null,updated_at=now() where lease_token=p_lease; update public.public_assistant_generation_budgets set input_tokens=input_tokens+p_input_tokens,output_tokens=output_tokens+p_output_tokens,updated_at=now() where period_start=current_date; return found; end; $$;
revoke all on function public.public_assistant_content_version(),public.public_assistant_search_chunks(extensions.vector,text,text,integer),public.public_assistant_claim_index_job(),public.public_assistant_finish_index_job(uuid,uuid,uuid),public.public_assistant_fail_index_job(uuid,uuid,text),public.public_assistant_cancel_index_job(uuid,uuid),public.public_assistant_take_rate_limit(text,integer,integer),public.public_assistant_take_generation_slot(integer),public.public_assistant_release_generation_slot(uuid,integer,integer) from public,anon,authenticated; grant execute on function public.public_assistant_content_version(),public.public_assistant_search_chunks(extensions.vector,text,text,integer),public.public_assistant_claim_index_job(),public.public_assistant_finish_index_job(uuid,uuid,uuid),public.public_assistant_fail_index_job(uuid,uuid,text),public.public_assistant_cancel_index_job(uuid,uuid),public.public_assistant_take_rate_limit(text,integer,integer),public.public_assistant_take_generation_slot(integer),public.public_assistant_release_generation_slot(uuid,integer,integer) to service_role;
create or replace function public.public_assistant_queue_cms_source() returns trigger language plpgsql security definer set search_path=public as $$ declare v_type text:=tg_argv[0]; v_key text; v_version text; begin v_key:=case when tg_op='DELETE' then old.id else new.id end; delete from public.public_assistant_answer_cache; if tg_op='DELETE' then update public.public_assistant_sources set publication_status='unpublished',updated_at=now() where source_type=v_type and source_key=v_key and publication_status='published'; return old; end if; if coalesce(new.status,'Draft')<>'Published' then update public.public_assistant_sources set publication_status='unpublished',updated_at=now() where source_type=v_type and source_key=v_key and publication_status='published'; return new; end if; v_version:=coalesce(new.updated_at::text,md5(to_jsonb(new)::text)); insert into public.public_assistant_index_jobs(source_type,source_key,source_version) values(v_type,v_key,v_version) on conflict(source_type,source_key,source_version) do update set state='queued',next_attempt_at=now(),error_code=null,error=null,updated_at=now(); return new; end; $$;
create trigger public_assistant_courses_queue after insert or update or delete on public.cms_courses for each row execute function public.public_assistant_queue_cms_source('course'); create trigger public_assistant_pages_queue after insert or update or delete on public.cms_pages for each row execute function public.public_assistant_queue_cms_source('page'); create trigger public_assistant_documents_queue after insert or update or delete on public.cms_documents for each row execute function public.public_assistant_queue_cms_source('document');
create or replace function public.public_assistant_invalidate_faq_cache() returns trigger language plpgsql security definer set search_path=public as $$ begin delete from public.public_assistant_answer_cache; return coalesce(new,old); end; $$; create trigger public_assistant_faq_cache_invalidate after insert or update or delete on public.public_assistant_faqs for each row execute function public.public_assistant_invalidate_faq_cache();
create or replace function public.cms_is_staff() returns boolean language sql stable security definer set search_path=public as $$ select auth.uid() is not null and exists(select 1 from public.cms_users u where u.status='Active' and u.auth_user_id=auth.uid()); $$; create or replace function public.cms_is_admin() returns boolean language sql stable security definer set search_path=public as $$ select auth.uid() is not null and exists(select 1 from public.cms_users u where u.status='Active' and u.role='Admin' and u.auth_user_id=auth.uid()); $$;

-- Documents are opt-in: Published alone never authorises AI ingestion.
alter table public.cms_documents add column if not exists assistant_publication_approved boolean not null default false;
create table public.public_assistant_document_text (
 id uuid primary key default gen_random_uuid(), document_id text not null, source_version text not null, file_hash text not null,
 original_text text not null, cleaned_text text not null, extraction_method text not null, extraction_version text not null,
 processing_status text not null check(processing_status in ('processing','complete','partial','failed','superseded')),
 warning jsonb not null default '[]'::jsonb, extracted_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 unique(document_id,source_version,file_hash)
);
create table public.public_assistant_document_pages (
 id uuid primary key default gen_random_uuid(), document_text_id uuid not null references public.public_assistant_document_text(id) on delete cascade,
 page_number integer not null check(page_number > 0), original_text text not null default '', cleaned_text text not null default '', status text not null check(status in ('digital','ocr','empty','partial','failed')), warnings jsonb not null default '[]'::jsonb, unique(document_text_id,page_number)
);
create table public.public_assistant_document_corrections (
 id uuid primary key default gen_random_uuid(), document_text_id uuid not null references public.public_assistant_document_text(id) on delete cascade, page_number integer, replacement_text text not null, reason text not null, created_by uuid references auth.users(id), created_at timestamptz not null default now(), approved_at timestamptz
);
alter table public.public_assistant_document_text enable row level security; alter table public.public_assistant_document_pages enable row level security; alter table public.public_assistant_document_corrections enable row level security;
revoke all on public.public_assistant_document_text,public.public_assistant_document_pages,public.public_assistant_document_corrections from anon,authenticated;
create policy public_assistant_document_text_staff_read on public.public_assistant_document_text for select to authenticated using(public.cms_is_staff());
create policy public_assistant_document_pages_staff_read on public.public_assistant_document_pages for select to authenticated using(public.cms_is_staff());
create policy public_assistant_document_corrections_staff_read on public.public_assistant_document_corrections for select to authenticated using(public.cms_is_staff());
create policy public_assistant_document_corrections_admin_write on public.public_assistant_document_corrections for all to authenticated using(public.cms_is_admin()) with check(public.cms_is_admin());
commit;
